val names = listOf("Ahmed", "Ali")
val ages = listOf(30, 25, 40) // longer — extra element silently ignored

val users = names.zip(ages) { name, age -> User(name, age) }
// [User("Ahmed", 30), User("Ali", 25)]

data class Order(val items: List<OrderItem>)

val allItems: List<OrderItem> = orders.flatMap { it.items }
// vs: orders.map { it.items }.flatten() — extra intermediate nested list

val transactions = listOf(100, -30, 50, -20)
val runningBalance = transactions.scan(0) { acc, tx -> acc + tx }
// [0, 100, 70, 120, 100] — includes every intermediate step

val sorted = users.sortedWith(
    compareByDescending<User> { it.priority }.thenBy { it.name }
) // highest priority first, alphabetical among ties

val items = buildList {
    add("always included")
    if (includeExtra) add("conditional item")
    addAll(otherSource)
} // returns List<String>, immutable outside this block

val powersOfTwo = generateSequence(1) { it * 2 }
    .takeWhile { it < 1000 }
    .toList() // [1, 2, 4, 8, ..., 512] — computed lazily, never infinite in memory

val namesByDept: Map<String, List<String>> =
    employees.groupBy(keySelector = { it.department }, valueTransform = { it.name })
// one pass, not groupBy{...}.mapValues{...}

val results = emptyList<Order>()

// results.first() // throws NoSuchElementException
val firstOrder = results.firstOrNull() ?: return // safe, explicit empty handling

items.forEach { println(it) } // simple per-element action

items.forEachIndexed { index, item -> println("$index: $item") }

// Needs break/continue? Use a for-loop instead of forEach
for (item in items) { if (item.isInvalid) break }

val result = largeList.asSequence()
    .filter { it.isActive }
    .map { it.toDto() }
    .take(10)
    .toList() // only materializes once, at the end

val usersById: Map<String, User> = users.associateBy { it.id }

// O(1) per lookup instead of O(n)
val user = usersById[targetId]

val ordersByStatus: Map<OrderStatus, Int> =
    orders.groupingBy { it.status }.eachCount()

// vs. manual: val map = mutableMapOf<OrderStatus, Int>(); for (o in orders) { map[o.status] = (map[o.status] ?: 0) + 1 }

val numbers = listOf(1, 2, 3, 4, 5, 6)

val evenDoubled = numbers
    .filter { it % 2 == 0 }   // [2, 4, 6]
    .map { it * 2 }            // [4, 8, 12]

// Transform objects
val names = users
    .filter { it.isActive }
    .map { it.displayName }

data class Student(val name: String, val grade: String)

val students = listOf(
    Student("Alice", "A"),
    Student("Bob", "B"),
    Student("Carol", "A"),
)

val byGrade = students.groupBy { it.grade }
// { "A" -> [Alice, Carol], "B" -> [Bob] }

// Count per grade
val counts = students.groupingBy { it.grade }.eachCount()
// { "A" -> 2, "B" -> 1 }

// Eager — creates 2 intermediate lists
val result = hugeList
    .map { it.name }        // new list
    .filter { it.length > 3 } // another new list
    .first()

// Lazy — processes one element at a time, stops early
val result = hugeList.asSequence()
    .map { it.name }
    .filter { it.length > 3 }
    .first()  // stops as soon as one match is found
